files.inner.sh:
export PYTHONDONTWRITEBYTECODE=1
X() { /usr/bin/python3 ext2check.py "$@"; }
O() { /usr/bin/python3 outcome.py "$@"; }
fds() { local a=(/proc/$BASHPID/fd/*); n=${#a[@]}; }
/usr/bin/python3 -c 'import sys; open(sys.argv[1], "wb").truncate(1048576)' small/img
fds; before=$n
{ mkfs small/img
} >enospc.out 2>enospc.err; O enospc "$?" enospc.out enospc.err 'No space left on device'
fds; after=$n
/usr/bin/python3 -c 'import os; print("length", os.path.getsize("small/img"))'
[[ $before == "$after" ]] && echo "descriptors unchanged" || echo "descriptors $before -> $after"

